	@Test
	void unorderedCloseFailureCannotPublishSavedScalarAttempt() throws IOException {
		TupleExpr target = telemetryTarget();
		RowState row = row(target);
		AtomicInteger calls = new AtomicInteger();
		AtomicInteger closes = new AtomicInteger();
		AtomicReference<NativeScalarFilterAttempt> observedAttempt = new AtomicReference<>();
		IllegalStateException closeFailure = new IllegalStateException("unordered filter close failed");
		NativeBooleanFilter filter = new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState current) {
				calls.incrementAndGet();
				observedAttempt.set(current.scalarFilterAttempt);
				return true;
			}

			@Override
			public void close() {
				closes.incrementAndGet();
				throw closeFailure;
			}
		};
		Selected selected = selectDirect(row, target,
				() -> NativeUnorderedInput.rows(row, new FilterCursor(rows(row, 1), filter, row)));
		NativeScalarFilterAttempt owner = selected.input().scalarFilterAttempt;

		assertThat(selected.input().advance()).isTrue();
		Throwable observedCloseFailure = catchThrowable(() -> selected.input().close(false));
		owner.accept();
		selected.input().close(false);
		owner.accept();

		assertAll("failed producer cleanup permanently rejects saved scalar work",
				() -> assertThat(observedAttempt.get()).isSameAs(owner),
				() -> assertThat(calls).hasValue(1),
				() -> assertThat(closes).hasValue(1),
				() -> assertThat(observedCloseFailure).isSameAs(closeFailure),
				() -> assertThat(metric(target)).as("later acceptance cannot publish the failed attempt").isNull());
	}

