	private static void assertAcceptedParallelCleanupFailure(boolean failDuringNext) throws IOException {
		TupleExpr target = telemetryTarget();
		RowState consumerRow = row(target);
		AtomicInteger calls = new AtomicInteger();
		NativeBooleanFilter templateFilter = new WorkerCountingFilter(calls);
		PatternPlan root = new PatternPlan(Term.slot(0), Term.constant(7L), Term.constant(8L), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 2D);
		MultiJoinPlan templatePlan = new MultiJoinPlan(new SlotPlan[] { root },
				new MaskedFilter[] { new MaskedFilter(templateFilter, 1L, 0) });
		NativeLmdbQuerySource.ParallelSource workerSource = mock(NativeLmdbQuerySource.ParallelSource.class);
		NativeLmdbQuerySource.ParallelSource producerSource = mock(NativeLmdbQuerySource.ParallelSource.class);
		IllegalStateException closeFailure = new IllegalStateException("worker source close failed");
		doThrow(closeFailure).when(workerSource).close();
		MultiJoinPlan workerPlan = LmdbNativeParallelPipelines.forkWorkerPlan(templatePlan,
				NativeScalarPlan.WorkerContext.forSource(workerSource, null));
		NativeRowsStep step = new NativeRowsStep(workerSource, templatePlan, consumerRow.layout, new int[] { 0 },
				new String[] { "value" }, false, new int[0], new boolean[0], 0L, -1L, false, null, target, null,
				Set.of(), null, null);
		LmdbNativeParallelPipelines.ParallelRowCursor cursor = new LmdbNativeParallelPipelines.ParallelRowCursor(step,
				consumerRow, root, new MultiJoinPlan[] { workerPlan },
				new NativeLmdbQuerySource.ParallelSource[] { workerSource, producerSource },
				new LmdbNativeParallelPipelines.TaskReservation(0), false);
		cursor.producerInitialized = true;
		cursor.producerScanComplete = true;
		cursor.input.add(new LmdbNativeExchange.Morsel(new long[] { 1L, 7L, 8L, 0L, 2L, 7L, 8L, 0L }, 2));
		cursor.input.add(LmdbNativeExchange.Morsel.POISON);

		String previousAdaptive = System.getProperty(LmdbNativeAdaptiveFilterPlacement.ENABLED_PROPERTY);
		String previousChunk = System.getProperty("rdf4j.lmdb.chunkPipeline.externalRoot.experimental");
		System.setProperty(LmdbNativeAdaptiveFilterPlacement.ENABLED_PROPERTY, "false");
		System.setProperty("rdf4j.lmdb.chunkPipeline.externalRoot.experimental", "false");
		try {
			Selected selected = selectDirect(consumerRow, target, () -> {
				cursor.runTask(() -> cursor.runWorker(0, workerPlan), workerPlan, workerSource);
				assertThat(cursor.cleanupFailures).containsExactly(closeFailure);
				return NativeUnorderedInput.rows(consumerRow, cursor);
			});
			selected.input().observeOnClose(selected.selection());
			RowCursor rows = selected.input().materializedRows();
			assertThat(rows.next()).isTrue();
			assertThat(consumerRow.slots[0]).isEqualTo(1L);
			assertThat(calls).hasValue(2);

			Executable phaseAssertions;
			if (failDuringNext) {
				NativeScalarFilterAttempt owner = selected.input().scalarFilterAttempt;
				assertThat(owner).isNotNull();
				assertThat(rows.next()).isTrue();
				assertThat(consumerRow.slots[0]).isEqualTo(2L);
				Throwable nextThrown = catchThrowable(rows::next);
				// Failure must already be terminal in the shared carrier, before a wrapper's later close.
				owner.accept();
				Throwable closeThrown = catchThrowable(rows::close);
				rows.close();
				owner.accept();
				phaseAssertions = () -> assertAll(
						"a pull cleanup failure stays terminal through idempotent adoption and close",
						() -> assertThat(nextThrown).isSameAs(closeFailure),
						() -> assertThat(closeThrown).as("idempotent close must not rethrow").isNull(),
						() -> assertThat(closeFailure.getSuppressed()).isEmpty(),
						() -> assertThat(calls).hasValue(2),
						() -> assertThat(consumerRow.scalarFilterAttempt).isSameAs(owner.parent()),
						() -> assertThat(metric(target)).as("failed shared work can never publish its two calls")
								.isNull());
			} else {
				Throwable closeThrown = catchThrowable(rows::close);
				phaseAssertions = () -> assertAll(
						"worker cleanup must succeed before accepted scalar work is published",
						() -> assertThat(closeThrown).isSameAs(closeFailure),
						() -> assertThat(metric(target)).isNull());
			}
			assertAll("worker and producer resources settle once after either cleanup boundary",
					phaseAssertions,
					() -> assertThat(cursor.tasks.getCount()).isZero(),
					() -> verify(workerSource).close(),
					() -> verify(producerSource).close());
		} finally {
			if (cursor.tasks.getCount() > 0L) {
				cursor.tasks.countDown();
			}
			try {
				cursor.close();
			} finally {
				try {
					consumerRow.memoryScope.close();
				} finally {
					restoreProperty(LmdbNativeAdaptiveFilterPlacement.ENABLED_PROPERTY, previousAdaptive);
					restoreProperty("rdf4j.lmdb.chunkPipeline.externalRoot.experimental", previousChunk);
				}
			}
		}
	}

	@Test
	void parallelClosePromotesCleanupFailureOverSuppressionDisabledDeadline() {
		TupleExpr target = telemetryTarget();
		RowState consumerRow = row(target);
		NativeLmdbQuerySource.ParallelSource workerSource = mock(NativeLmdbQuerySource.ParallelSource.class);
		NativeLmdbQuerySource.ParallelSource producerSource = mock(NativeLmdbQuerySource.ParallelSource.class);
		PatternPlan root = new PatternPlan(Term.slot(0), Term.constant(7L), Term.constant(8L), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 1D);
		MultiJoinPlan workerPlan = new MultiJoinPlan(new SlotPlan[] { root }, new MaskedFilter[0]);
		NativeRowsStep step = new NativeRowsStep(workerSource, workerPlan, consumerRow.layout, new int[] { 0 },
				new String[] { "value" }, false, new int[0], new boolean[0], 0L, -1L, false, null, target, null,
				Set.of(), null, null);
		LmdbNativeParallelPipelines.ParallelRowCursor cursor = new LmdbNativeParallelPipelines.ParallelRowCursor(step,
				consumerRow, root, new MultiJoinPlan[] { workerPlan },
				new NativeLmdbQuerySource.ParallelSource[] { workerSource, producerSource },
				new LmdbNativeParallelPipelines.TaskReservation(0), false);
		RuntimeException deadline = NativeCancellationTestAccess.probeDeadlineSignal();
		IllegalStateException closeFailure = new IllegalStateException("worker close after deadline failed");
		try {
			cursor.recordTaskFailure(deadline);
			cursor.recordCleanupFailure(closeFailure);
			cursor.taskFinished();

			Throwable observed = catchThrowable(cursor::close);

			assertThat(observed).isSameAs(closeFailure);
			assertThat(closeFailure.getSuppressed()).containsExactly(deadline);
			assertThat(deadline.getSuppressed()).isEmpty();
		} finally {
			cursor.close();
			workerSource.close();
			producerSource.close();
		}
	}

