	@Test
	void capacityTrialCleanupFailureAbortsBeforeFallback() throws IOException {
		withBufferRows(1, () -> {
			TupleExpr target = telemetryTarget();
			RowState row = row(target);
			AtomicInteger trialCalls = new AtomicInteger();
			AtomicInteger producerCloses = new AtomicInteger();
			AtomicInteger filterCloses = new AtomicInteger();
			AtomicInteger fallbackOpens = new AtomicInteger();
			IllegalStateException closeFailure = new IllegalStateException("capacity trial close failed");
			RowCursor producer = new RowCursor() {
				private int emitted;

				@Override
				public boolean next() {
					if (emitted == 4) {
						return false;
					}
					row.slots[0] = ++emitted;
					row.recomputeBoundMask();
					return true;
				}

				@Override
				public void close() {
					producerCloses.incrementAndGet();
				}
			};
			NativeBooleanFilter filter = new NativeBooleanFilter() {
				@Override
				public boolean accept(RowState input) {
					trialCalls.incrementAndGet();
					return true;
				}

				@Override
				public void close() {
					filterCloses.incrementAndGet();
					throw closeFailure;
				}
			};
			AtomicReference<LmdbNativeStrategySelection<NativeUnorderedInput>> selected = new AtomicReference<>();
			Throwable failure;
			try (LmdbNativeStrategyArbiter<NativeUnorderedInput> arbiter = LmdbNativeStrategyArbiter
					.<NativeUnorderedInput>forModel(target, -1D, measuredModel())
					.probeHarness(new NativeProbeBufferHarness())
					.sharedRow(row)) {
				arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> {
					fallbackOpens.incrementAndGet();
					return input(row, new AtomicInteger(), 4);
				}, LmdbNativeWork.exact(1_000D), LmdbNativeAttemptMetrics.PATH_BATCH, () -> {
				}));
				arbiter.offer(() -> new LmdbNativeStrategyProposal<>(
						() -> NativeUnorderedInput.rows(row, new FilterCursor(producer, filter, row)),
						LmdbNativeWork.UNKNOWN, LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, () -> {
						}));
				failure = catchThrowable(() -> selected.set(arbiter.selectWithObservation()));
			} finally {
				try {
					if (selected.get() != null) {
						try {
							selected.get().value().close(false);
						} finally {
							selected.get().close();
						}
					}
				} finally {
					row.memoryScope.close();
				}
			}
			assertAll("a failed trial release must escape rather than become a clean capacity decline",
					() -> assertThat(failure).isSameAs(closeFailure),
					() -> assertThat(closeFailure.getSuppressed())
							.containsExactly(LmdbNativeProbeDeadlineExceeded.INSTANCE),
					() -> assertThat(trialCalls).as("the actual FilterCursor overflowed a one-row buffer")
							.hasValue(2),
					() -> assertThat(producerCloses).hasValue(1),
					() -> assertThat(filterCloses).hasValue(1),
					() -> assertThat(fallbackOpens).hasValue(0));
		});
	}

